/**
 * Rôle : Préparation de l'environnement avant le chargement de webextension-polyfill.
 * Entrées : Objet global (globalThis).
 * Sorties : Si l'exécution a lieu hors navigateur (ex. tests unitaires Vitest/jsdom), injecte une doublure mémoire complète afin que webextension-polyfill se charge sans lever d'exception.
 * Limites : Dans un vrai navigateur (Chrome, Firefox, Edge, Brave), globalThis.chrome.runtime.id est déjà défini et ce module ne modifie rien.
 */

import type Browser from "webextension-polyfill";

type StorageChangeRecord = Record<string, { oldValue?: unknown; newValue?: unknown }>;
type StorageListener = (changes: StorageChangeRecord, areaName: string) => void;
type MessageListener = (
  message: unknown,
  sender: Browser.Runtime.MessageSender
) => Promise<unknown> | unknown;

function ensureExtensionEnv(): void {
  const g = globalThis as unknown as {
    browser?: unknown;
    chrome?: { runtime?: { id?: string } };
  };

  if (g.chrome?.runtime?.id) {
    return;
  }

  const memoryStore: Record<string, unknown> = {};
  const storageListeners = new Set<StorageListener>();
  const messageListeners = new Set<MessageListener>();

  const mockBrowser = {
    runtime: {
      id: "linguafin-test-env",
      async sendMessage(message: unknown) {
        for (const listener of messageListeners) {
          const resp = await listener(message, {} as Browser.Runtime.MessageSender);
          if (resp !== undefined) {
            return resp;
          }
        }
        return undefined;
      },
      onMessage: {
        addListener(cb: MessageListener) {
          messageListeners.add(cb);
        },
        removeListener(cb: MessageListener) {
          messageListeners.delete(cb);
        }
      }
    },
    storage: {
      local: {
        async get(keys?: string | string[] | Record<string, unknown> | null) {
          if (keys === null || keys === undefined) {
            return { ...memoryStore };
          }
          if (typeof keys === "string") {
            return keys in memoryStore ? { [keys]: memoryStore[keys] } : {};
          }
          if (Array.isArray(keys)) {
            const out: Record<string, unknown> = {};
            for (const k of keys) {
              if (k in memoryStore) {
                out[k] = memoryStore[k];
              }
            }
            return out;
          }
          const out: Record<string, unknown> = {};
          for (const [k, defVal] of Object.entries(keys)) {
            out[k] = k in memoryStore ? memoryStore[k] : defVal;
          }
          return out;
        },
        async set(items: Record<string, unknown>) {
          const changes: StorageChangeRecord = {};
          for (const [k, v] of Object.entries(items)) {
            changes[k] = { oldValue: memoryStore[k], newValue: v };
            memoryStore[k] = v;
          }
          for (const listener of storageListeners) {
            listener(changes, "local");
          }
        },
        async clear() {
          for (const k of Object.keys(memoryStore)) {
            delete memoryStore[k];
          }
        }
      },
      onChanged: {
        addListener(cb: StorageListener) {
          storageListeners.add(cb);
        },
        removeListener(cb: StorageListener) {
          storageListeners.delete(cb);
        }
      }
    },
    tabs: {
      async query() {
        return [{ id: 1, url: "http://localhost:5173/account.html" }];
      },
      async sendMessage(_tabId: number, message: unknown) {
        for (const listener of messageListeners) {
          const resp = await listener(message, {} as Browser.Runtime.MessageSender);
          if (resp !== undefined) {
            return resp;
          }
        }
        return undefined;
      }
    },
    i18n: {
      getUILanguage() {
        return "fr";
      }
    }
  };

  g.chrome = mockBrowser;
  g.browser = mockBrowser;
}

ensureExtensionEnv();

