/**
 * Rôle : Fournisseur de traduction via l'API Google Translate (translate.googleapis.com),
 *        exécuté après protection des valeurs financières (protector.ts) et suivi de la vérification stricte (verifier.ts).
 * Entrées : Objet Protected { text, tokens }, langue source (ou "auto") et langue cible.
 * Sorties : Chaîne traduite avec normalisation des jetons {{n}}, ou null en cas d'indisponibilité réseau.
 * Limites : Ne transmet jamais de montants, numéros de téléphone, dates ou IBAN en clair (uniquement des jetons {{0}}, {{1}}).
 */

import { safeRuntimeSendMessage } from "../../shared/ext.js";
import type {
  GoogleTranslateMessage,
  RemoteTranslateResponse
} from "../../shared/messages.js";
import type { LangCode, Protected, TranslationProvider } from "../types.js";

const GOOGLE_CLIENTS5_ENDPOINT = "https://clients5.google.com/translate_a/t";
const GOOGLE_GTX_ENDPOINT = "https://translate.googleapis.com/translate_a/single";
const REQUEST_TIMEOUT_MS = 6000;

/**
 * Langues nationales camerounaises non supportées nativement par l'API standard Google Translate.
 * Celles-ci doivent être traitées exclusivement par notre LexiconProvider local ou le ModelServerProvider.
 */
const UNSUPPORTED_BY_GOOGLE = new Set<string>(["wes", "ewo", "dua"]);

/**
 * Normalise les jetons {{n}} éventuellement espacés par le moteur de traduction (ex. "{{ 0 }}" -> "{{0}}").
 */
export function normalizeProtectedTokens(translated: string): string {
  return translated
    .replace(/\{\s*\{\s*(\d+)\s*\}\s*\}/g, "{{$1}}")
    .replace(/<\s*x\s+id\s*=\s*["'](\d+)["']\s*\/\s*>/gi, '<x id="$1"/>');
}

/**
 * Extrait le texte traduit depuis les différents formats de réponse JSON de Google Translate :
 * - ["Texte traduit"] (format clients5)
 * - [["Texte traduit", "langue_source"]] (format clients5 avec sl=auto)
 * - [[["Texte traduit", "source", null, null]]] (format gtx/single)
 */
export function extractGoogleTranslateResponse(data: unknown): string | null {
  if (typeof data === "string") {
    return data.trim();
  }
  if (!Array.isArray(data) || data.length === 0) {
    return null;
  }

  // Format format clients5 direct : ["Texte traduit"]
  if (typeof data[0] === "string") {
    return data.filter((c): c is string => typeof c === "string").join("");
  }

  // Format array : soit [["Texte", "lang"]] (clients5) soit [[["Texte", ...]]] (gtx)
  if (Array.isArray(data[0])) {
    const sub = data[0];
    if (typeof sub[0] === "string") {
      return sub[0];
    }
    if (Array.isArray(sub[0]) && typeof sub[0][0] === "string") {
      const chunks: string[] = [];
      for (const seg of data[0]) {
        if (Array.isArray(seg) && typeof seg[0] === "string") {
          chunks.push(seg[0]);
        }
      }
      return chunks.length > 0 ? chunks.join("") : null;
    }
  }

  return null;
}

/**
 * Appel HTTP direct à l'API Google Translate (utilisé par le service worker d'arrière-plan ou en repli direct).
 */
export async function fetchGoogleTranslateDirect(
  protectedText: string,
  src: LangCode | "auto",
  tgt: LangCode
): Promise<string | null> {
  if (!protectedText || !protectedText.trim()) {
    return null;
  }

  const sl = src && src !== "unknown" ? src : "auto";

  // 1. Essai prioritaire via clients5.google.com (endpoint standard haute disponibilité utilisé par les extensions Chrome)
  const clients5Url =
    `${GOOGLE_CLIENTS5_ENDPOINT}?client=dict-chrome-ex&sl=${encodeURIComponent(sl)}` +
    `&tl=${encodeURIComponent(tgt)}&q=${encodeURIComponent(protectedText)}`;

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  try {
    const response = await fetch(clients5Url, {
      method: "GET",
      headers: {
        Accept: "application/json, text/plain, */*"
      },
      signal: controller.signal
    });

    if (response.ok) {
      const data = (await response.json()) as unknown;
      const extracted = extractGoogleTranslateResponse(data);
      if (extracted && extracted.length > 0) {
        return normalizeProtectedTokens(extracted);
      }
    }
  } catch {
    // Repli sur le second endpoint ci-dessous
  } finally {
    clearTimeout(timer);
  }

  // 2. Repli secondaire via translate.googleapis.com (gtx)
  const gtxController = new AbortController();
  const gtxTimer = setTimeout(() => gtxController.abort(), REQUEST_TIMEOUT_MS);

  try {
    const gtxUrl =
      `${GOOGLE_GTX_ENDPOINT}?client=gtx&sl=${encodeURIComponent(sl)}` +
      `&tl=${encodeURIComponent(tgt)}&dt=t&q=${encodeURIComponent(protectedText)}`;

    const response = await fetch(gtxUrl, {
      method: "GET",
      headers: {
        Accept: "application/json, text/plain, */*"
      },
      signal: gtxController.signal
    });

    if (response.ok) {
      const data = (await response.json()) as unknown;
      const extracted = extractGoogleTranslateResponse(data);
      if (extracted && extracted.length > 0) {
        return normalizeProtectedTokens(extracted);
      }
    }
    return null;
  } catch {
    return null;
  } finally {
    clearTimeout(gtxTimer);
  }
}

export class GoogleTranslateProvider implements TranslationProvider {
  public readonly id = "google-translate";
  private readonly inFlight = new Map<string, Promise<string | null>>();

  public canTranslate(src: LangCode, tgt: LangCode): boolean {
    if (!tgt || src === tgt) {
      return false;
    }
    if (UNSUPPORTED_BY_GOOGLE.has(tgt) || UNSUPPORTED_BY_GOOGLE.has(src)) {
      return false;
    }
    return true;
  }

  public async translate(
    input: Protected,
    src: LangCode,
    tgt: LangCode,
    _ctx: { critical: boolean }
  ): Promise<string | null> {
    if (!input.text || !this.canTranslate(src, tgt)) {
      return null;
    }

    const key = `${src}|${tgt}|${input.text}`;
    const existing = this.inFlight.get(key);
    if (existing) {
      return existing;
    }

    const promise = this.executeTranslation(input.text, src, tgt).finally(() => {
      this.inFlight.delete(key);
    });

    this.inFlight.set(key, promise);
    return promise;
  }

  private async executeTranslation(
    protectedText: string,
    src: LangCode | "auto",
    tgt: LangCode
  ): Promise<string | null> {
    // 1. Passer en priorité par le script d'arrière-plan de l'extension (contourne le CORS/CSP des pages hôtes)
    const msg: GoogleTranslateMessage = {
      type: "GOOGLE_TRANSLATE",
      payload: {
        protectedText,
        src,
        tgt
      }
    };
    const response = await safeRuntimeSendMessage<RemoteTranslateResponse>(msg);
    if (response && response.ok && typeof response.translatedText === "string") {
      return normalizeProtectedTokens(response.translatedText);
    }

    // 2. Appel direct en repli (ex. si le service worker vient d'être rechargé)
    return fetchGoogleTranslateDirect(protectedText, src, tgt);
  }
}

