/**
 * Rôle : Script d'arrière-plan (service worker sous Chromium, event page sous Firefox) exécutant :
 *   1. Les requêtes vers l'API Google Translate (GOOGLE_TRANSLATE) pour traduire toute la page sans blocage CORS/CSP.
 *   2. Les requêtes vers votre serveur hébergé exécutant un modèle préconçu (MODEL_SERVER_TRANSLATE).
 *   3. Les requêtes opt-in compatibles LibreTranslate (REMOTE_TRANSLATE).
 * Entrées : Messages contenant uniquement du texte déjà protégé par jetons ({{n}}).
 * Sorties : Objet RemoteTranslateResponse { ok, translatedText, error }.
 * Limites : Bloque systématiquement tout envoi si le texte contient encore des valeurs sensibles non remplacées par des jetons {{n}}.
 */

import { protect } from "../core/protector.js";
import { fetchGoogleTranslateDirect } from "../core/providers/google-translate-provider.js";
import { fetchModelServerDirect } from "../core/providers/model-server-provider.js";
import { browser } from "../shared/ext.js";
import {
  isExtensionMessage,
  type GoogleTranslateMessage,
  type ModelServerTranslateMessage,
  type RemoteTranslateMessage,
  type RemoteTranslateResponse
} from "../shared/messages.js";
import { getSettings } from "../shared/settings.js";

const FETCH_TIMEOUT_MS = 4000;

/**
 * Exécute la requête vers l'API Google Translate après contrôle d'absence de valeurs sensibles en clair.
 */
export async function handleGoogleTranslateRequest(
  msg: GoogleTranslateMessage
): Promise<RemoteTranslateResponse> {
  const { protectedText, src, tgt } = msg.payload;

  const safetyCheck = protect(protectedText);
  if (safetyCheck.tokens.length > 0) {
    return { ok: false, error: "unprotected-sensitive-data-blocked" };
  }

  const translatedText = await fetchGoogleTranslateDirect(protectedText, src, tgt);
  if (!translatedText) {
    return { ok: false, error: "google-translate-failed" };
  }

  return {
    ok: true,
    translatedText
  };
}

/**
 * Exécute la requête vers le serveur hébergé du modèle préconçu après contrôle d'absence de valeurs sensibles en clair.
 */
export async function handleModelServerTranslateRequest(
  msg: ModelServerTranslateMessage
): Promise<RemoteTranslateResponse> {
  const settings = await getSettings();
  const { protectedText, src, tgt } = msg.payload;
  const serverUrl = (msg.payload.serverUrl || settings.modelServerUrl || "").trim();
  const apiKey = (msg.payload.apiKey || settings.modelServerApiKey || "").trim();

  if (!serverUrl || !/^https?:\/\//i.test(serverUrl)) {
    return { ok: false, error: "invalid-model-server-endpoint" };
  }

  const safetyCheck = protect(protectedText);
  if (safetyCheck.tokens.length > 0) {
    return { ok: false, error: "unprotected-sensitive-data-blocked" };
  }

  const translatedText = await fetchModelServerDirect(
    protectedText,
    src,
    tgt,
    serverUrl,
    apiKey || undefined
  );

  if (!translatedText) {
    return { ok: false, error: "model-server-failed" };
  }

  return {
    ok: true,
    translatedText
  };
}

/**
 * Exécute la requête vers un point de terminaison compatible LibreTranslate (POST /translate).
 */
export async function handleRemoteTranslateRequest(
  msg: RemoteTranslateMessage
): Promise<RemoteTranslateResponse> {
  const settings = await getSettings();
  if (!settings.remoteEnabled) {
    return { ok: false, error: "remote-disabled" };
  }

  const endpoint = (msg.payload.remoteUrl || settings.remoteUrl).trim();
  if (!endpoint || !/^https?:\/\//i.test(endpoint)) {
    return { ok: false, error: "invalid-endpoint" };
  }

  const { protectedText, src, tgt } = msg.payload;

  // Vérification défensive : s'assurer qu'aucune valeur sensible non protégée n'est présente avant l'envoi réseau
  const safetyCheck = protect(protectedText);
  if (safetyCheck.tokens.length > 0) {
    return { ok: false, error: "unprotected-sensitive-data-blocked" };
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);

  try {
    const response = await fetch(endpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        q: protectedText,
        source: src,
        target: tgt,
        format: "text"
      }),
      signal: controller.signal
    });

    if (!response.ok) {
      return { ok: false, error: `http-${response.status}` };
    }

    const data = (await response.json()) as { translatedText?: unknown };
    if (typeof data?.translatedText !== "string") {
      return { ok: false, error: "invalid-response-payload" };
    }

    return {
      ok: true,
      translatedText: data.translatedText
    };
  } catch {
    return { ok: false, error: "network-or-timeout-error" };
  } finally {
    clearTimeout(timer);
  }
}

export function registerBackgroundListeners(): void {
  browser.runtime.onMessage.addListener((msg: unknown) => {
    if (!isExtensionMessage(msg)) {
      return undefined;
    }
    if (msg.type === "GOOGLE_TRANSLATE") {
      return handleGoogleTranslateRequest(msg);
    }
    if (msg.type === "MODEL_SERVER_TRANSLATE") {
      return handleModelServerTranslateRequest(msg);
    }
    if (msg.type === "REMOTE_TRANSLATE") {
      return handleRemoteTranslateRequest(msg);
    }
    return undefined;
  });

  // Lors de l'installation ou du rechargement de l'extension (🔄 sur chrome://extensions),
  // réinjecter automatiquement content/index.js dans les onglets http/https déjà ouverts
  // afin d'éviter l'erreur "Extension context invalidated" sur les onglets non rafraîchis.
  try {
    browser.runtime.onInstalled?.addListener(() => {
      void reinjectContentScriptsInOpenTabs();
    });
  } catch {
    // Ignorer hors environnement d'extension complet
  }
}

async function reinjectContentScriptsInOpenTabs(): Promise<void> {
  try {
    const tabs = await browser.tabs.query({ url: ["http://*/*", "https://*/*"] });
    for (const tab of tabs) {
      if (typeof tab.id === "number") {
        try {
          await browser.scripting?.executeScript?.({
            target: { tabId: tab.id },
            files: ["content/index.js"]
          });
        } catch {
          // Ignorer les onglets protégés du navigateur (ex. Chrome Web Store)
        }
      }
    }
  } catch {
    // Ignorer
  }
}

const isTestEnv =
  typeof process !== "undefined" &&
  Boolean(process.env?.VITEST);

if (!isTestEnv) {
  registerBackgroundListeners();
}
