/**
 * Rôle : Point d'entrée unique vers l'API WebExtension multi-navigateurs via webextension-polyfill (Section 3.2 et Section 11),
 *        avec vérification de validité du contexte d'extension (évite l'erreur "Extension context invalidated" sur Chrome après rechargement).
 * Entrées : Importations depuis src/shared/, src/content/, src/popup/ et src/core/providers/.
 * Sorties : Instance normalisée `browser` et utilitaires sécurisés `isExtensionContextValid` / `safeSendMessage`.
 * Limites : N'utiliser que les API communes à Chromium et Firefox.
 */

import "./polyfill-env.js";
import browser from "webextension-polyfill";

/**
 * Vérifie si le contexte de l'extension est toujours valide dans la page courante.
 * Sur Chrome/Brave/Edge, lorsque l'utilisateur recharge l'extension depuis chrome://extensions,
 * les anciens content scripts des onglets déjà ouverts voient `chrome.runtime.id` devenir `undefined`.
 */
export function isExtensionContextValid(): boolean {
  try {
    const g = globalThis as unknown as {
      chrome?: { runtime?: { id?: string } };
      browser?: { runtime?: { id?: string } };
    };
    const id = g.chrome?.runtime?.id ?? g.browser?.runtime?.id;
    return typeof id === "string" && id.length > 0;
  } catch {
    return false;
  }
}

/**
 * Envoie un message via browser.runtime.sendMessage en capturant proprement toute invalidation de contexte.
 */
export async function safeRuntimeSendMessage<T = unknown>(message: unknown): Promise<T | undefined> {
  if (!isExtensionContextValid()) {
    return undefined;
  }
  try {
    return (await browser.runtime.sendMessage(message)) as T | undefined;
  } catch {
    return undefined;
  }
}

export { browser };
export default browser;
