/**
 * Rôle : Module client dédié à la communication avec votre serveur hébergé exécutant un modèle de traduction préconçu
 *        (ex. modèle NMT / LLM spécialisé finance et langues camerounaises hébergé sur FastAPI, vLLM, HuggingFace ou Node.js).
 * Entrées : Texte protégé par jetons ({{0}}, {{1}}), langue source, langue cible et configuration du serveur (URL, clé API optionnelle).
 * Sorties : Chaîne traduite avec jetons {{n}} normalisés, soumise ensuite à verifier.ts avant affichage.
 * Limites : Ne transmet jamais de montants ou données personnelles en clair ; bascule proprement sur le fournisseur de repli si le serveur est hors ligne.
 */

import { safeRuntimeSendMessage } from "../../shared/ext.js";
import type {
  ModelServerTranslateMessage,
  RemoteTranslateResponse
} from "../../shared/messages.js";
import type { LangCode, Protected, TranslationProvider } from "../types.js";
import { normalizeProtectedTokens } from "./google-translate-provider.js";

const MODEL_SERVER_TIMEOUT_MS = 8000;

/**
 * Contrat de requête JSON envoyé au serveur hébergé du modèle préconçu.
 */
export interface ModelServerRequestPayload {
  /** Texte à traduire avec valeurs financières remplacées par {{0}}, {{1}}, etc. */
  text: string;
  /** Code langue source ("fr", "en", "auto", etc.) */
  source_lang: string;
  /** Code langue cible ("fr", "en", "wes", "ewo", "ff", "dua", etc.) */
  target_lang: string;
  /** Domaine métier pour guider le modèle préconçu */
  domain: "finance";
  /** Liste des jetons {{n}} qui doivent impérativement être restitués à l'identique */
  placeholders: string[];
  /** Compatibilité avec les serveurs attendant q / source / target */
  q: string;
  source: string;
  target: string;
}

/**
 * Formats de réponse JSON acceptés depuis le serveur du modèle préconçu.
 */
export interface ModelServerResponsePayload {
  translated_text?: string;
  translatedText?: string;
  translation?: string;
  output?: string;
  result?: string;
}

/**
 * Exécute l'appel HTTP POST vers le serveur hébergé du modèle préconçu.
 */
export async function fetchModelServerDirect(
  protectedText: string,
  src: LangCode | "auto",
  tgt: LangCode,
  serverUrl: string,
  apiKey?: string
): Promise<string | null> {
  const endpoint = serverUrl.trim();
  if (!endpoint || !/^https?:\/\//i.test(endpoint)) {
    return null;
  }

  const placeholders = protectedText.match(/\{\{\d+\}\}/g) ?? [];
  const bodyPayload: ModelServerRequestPayload = {
    text: protectedText,
    source_lang: src && src !== "unknown" ? src : "auto",
    target_lang: tgt,
    domain: "finance",
    placeholders,
    q: protectedText,
    source: src && src !== "unknown" ? src : "auto",
    target: tgt
  };

  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    Accept: "application/json"
  };

  if (apiKey && apiKey.trim().length > 0) {
    headers.Authorization = `Bearer ${apiKey.trim()}`;
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), MODEL_SERVER_TIMEOUT_MS);

  try {
    const response = await fetch(endpoint, {
      method: "POST",
      headers,
      body: JSON.stringify(bodyPayload),
      signal: controller.signal
    });

    if (!response.ok) {
      return null;
    }

    const data = (await response.json()) as ModelServerResponsePayload;
    const rawTranslated =
      data.translated_text ??
      data.translatedText ??
      data.translation ??
      data.output ??
      data.result;

    if (typeof rawTranslated !== "string" || rawTranslated.trim().length === 0) {
      return null;
    }

    return normalizeProtectedTokens(rawTranslated);
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

export class ModelServerProvider implements TranslationProvider {
  public readonly id = "custom-model-server";
  private serverUrl: string;
  private apiKey: string;
  private enabled: boolean;
  private readonly inFlight = new Map<string, Promise<string | null>>();

  constructor(options: { serverUrl?: string; apiKey?: string; enabled?: boolean } = {}) {
    this.serverUrl = (options.serverUrl ?? "").trim();
    this.apiKey = (options.apiKey ?? "").trim();
    this.enabled = Boolean(options.enabled);
  }

  /**
   * Met à jour dynamiquement la configuration du serveur du modèle préconçu.
   */
  public configure(config: { serverUrl?: string; apiKey?: string; enabled?: boolean }): void {
    if (config.serverUrl !== undefined) {
      this.serverUrl = config.serverUrl.trim();
    }
    if (config.apiKey !== undefined) {
      this.apiKey = config.apiKey.trim();
    }
    if (config.enabled !== undefined) {
      this.enabled = config.enabled;
    }
  }

  public isConfiguredAndEnabled(): boolean {
    return this.enabled && /^https?:\/\//i.test(this.serverUrl);
  }

  public canTranslate(src: LangCode, tgt: LangCode): boolean {
    if (!this.isConfiguredAndEnabled()) {
      return false;
    }
    return Boolean(tgt) && src !== tgt;
  }

  public async translate(
    input: Protected,
    src: LangCode,
    tgt: LangCode,
    ctx: { critical: boolean }
  ): Promise<string | null> {
    if (!input.text || !this.canTranslate(src, tgt)) {
      return null;
    }

    const key = `${this.serverUrl}|${src}|${tgt}|${input.text}`;
    const existing = this.inFlight.get(key);
    if (existing) {
      return existing;
    }

    const promise = this.executeModelRequest(input.text, src, tgt, ctx.critical).finally(() => {
      this.inFlight.delete(key);
    });

    this.inFlight.set(key, promise);
    return promise;
  }

  private async executeModelRequest(
    protectedText: string,
    src: LangCode | "auto",
    tgt: LangCode,
    critical: boolean
  ): Promise<string | null> {
    const msg: ModelServerTranslateMessage = {
      type: "MODEL_SERVER_TRANSLATE",
      payload: {
        protectedText,
        src,
        tgt,
        serverUrl: this.serverUrl,
        apiKey: this.apiKey || undefined,
        critical
      }
    };

    const response = await safeRuntimeSendMessage<RemoteTranslateResponse>(msg);
    if (response && response.ok && typeof response.translatedText === "string") {
      return normalizeProtectedTokens(response.translatedText);
    }

    return fetchModelServerDirect(protectedText, src, tgt, this.serverUrl, this.apiKey);
  }
}

